/**
 * Thin, typed helpers over the axios client.
 *
 * `Schemas` exposes the backend's OpenAPI components (generated by
 * `npm run api:types`), so response shapes are checked against the real API.
 */
import { api } from "@/lib/api";

import type { components } from "./openapi";

export type Schemas = components["schemas"];

export interface Page<T> {
  count: number;
  next: string | null;
  previous: string | null;
  results: T[];
}

type Params = Record<string, string | number | boolean | undefined | null>;

function clean(params?: Params) {
  if (!params) return undefined;
  return Object.fromEntries(Object.entries(params).filter(([, v]) => v !== undefined && v !== null && v !== ""));
}

export async function get<T>(path: string, params?: Params): Promise<T> {
  const { data } = await api.get<T>(path, { params: clean(params) });
  return data;
}

export async function post<T>(path: string, body?: unknown): Promise<T> {
  const { data } = await api.post<T>(path, body);
  return data;
}

export async function patch<T>(path: string, body: unknown): Promise<T> {
  const { data } = await api.patch<T>(path, body);
  return data;
}

export async function del(path: string): Promise<void> {
  await api.delete(path);
}

/** Every row of a paginated list endpoint (follows pages of 200). */
export async function getAll<T>(path: string, params?: Params): Promise<T[]> {
  const rows: T[] = [];
  let page = 1;
  for (;;) {
    const data = await get<Page<T>>(path, { ...params, page, page_size: 200 });
    rows.push(...data.results);
    if (!data.next) return rows;
    page += 1;
  }
}

/** Human message from a DRF error response (field errors flattened). */
export function errorMessage(error: unknown, fallback = "Something went wrong."): string {
  const data = (error as { response?: { data?: unknown } })?.response?.data;
  if (!data) return fallback;
  if (typeof data === "string") return data;
  if (Array.isArray(data)) return data.map(String).join(" ");
  if (typeof data === "object") {
    const obj = data as Record<string, unknown>;
    if (typeof obj.detail === "string") return obj.detail;
    const parts = Object.entries(obj).map(([k, v]) => {
      const msg = Array.isArray(v) ? v.join(" ") : typeof v === "object" ? JSON.stringify(v) : String(v);
      return k === "non_field_errors" ? msg : `${k.replace(/_/g, " ")}: ${msg}`;
    });
    return parts.join(" · ") || fallback;
  }
  return fallback;
}

/** "male" -> "Male", "half_day" -> "Half day" */
export function label(value: string | null | undefined): string {
  if (!value) return "";
  const s = value.replace(/_/g, " ");
  return s.charAt(0).toUpperCase() + s.slice(1);
}
